// Generates ../plate-data.ts: simplified lower-48 outline and interior state borders,
// already projected (us-atlas "albers" files: d3.geoAlbersUsa().scale(1300).translate([487.5, 305])).
// Usage (from the repo root): node src/graphics/tunnel3d/check/gen-plate.mjs
// Dev-only: the application imports the generated file, never us-atlas itself.
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mesh, merge } from 'topojson-client';

const here = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
const topo = JSON.parse(await readFile(require.resolve('us-atlas/states-albers-10m.json'), 'utf8'));

const TOL = 0.55; // projected units (about 1.7 miles)
const MIN_RING_AREA = 14; // drop islets smaller than this (projected units squared)
const EXCLUDE = new Set(['02', '15']); // Alaska, Hawaii
const lower48 = (g) => !EXCLUDE.has(String(g.id).padStart(2, '0')) && Number(g.id) <= 56;

const states = topo.objects.states;
const kept = states.geometries.filter(lower48);

function dp(pts, tol) {
  if (pts.length < 3) return pts;
  const keep = new Uint8Array(pts.length);
  keep[0] = keep[pts.length - 1] = 1;
  const stack = [[0, pts.length - 1]];
  while (stack.length) {
    const [a, b] = stack.pop();
    const [ax, ay] = pts[a];
    const [bx, by] = pts[b];
    const dx = bx - ax;
    const dy = by - ay;
    const len2 = dx * dx + dy * dy || 1e-12;
    let worst = -1;
    let wi = -1;
    for (let i = a + 1; i < b; i++) {
      const t = Math.max(0, Math.min(1, ((pts[i][0] - ax) * dx + (pts[i][1] - ay) * dy) / len2));
      const d = Math.hypot(pts[i][0] - (ax + t * dx), pts[i][1] - (ay + t * dy));
      if (d > worst) {
        worst = d;
        wi = i;
      }
    }
    if (worst > tol) {
      keep[wi] = 1;
      stack.push([a, wi], [wi, b]);
    }
  }
  return pts.filter((_, i) => keep[i]);
}

function ringArea(r) {
  let a = 0;
  for (let i = 0, j = r.length - 1; i < r.length; j = i++) a += r[j][0] * r[i][1] - r[i][0] * r[j][1];
  return Math.abs(a) / 2;
}

function selfIntersects(r) {
  // r is closed (first point repeated). O(n^2) is fine at this size.
  const n = r.length - 1;
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  for (let i = 0; i < n; i++) {
    for (let j = i + 2; j < n; j++) {
      if (i === 0 && j === n - 1) continue;
      const a = r[i], b = r[i + 1], c = r[j], d = r[j + 1];
      if (cross(a, b, c) * cross(a, b, d) < 0 && cross(c, d, a) * cross(c, d, b) < 0) return true;
    }
  }
  return false;
}

function simplifyRing(r, tol = TOL) {
  // Split a closed ring at its farthest point so Douglas-Peucker has two open halves.
  let far = 1;
  let fd = 0;
  for (let i = 1; i < r.length - 1; i++) {
    const d = Math.hypot(r[i][0] - r[0][0], r[i][1] - r[0][1]);
    if (d > fd) {
      fd = d;
      far = i;
    }
  }
  const a = dp(r.slice(0, far + 1), tol);
  const b = dp(r.slice(far), tol);
  const out = a.concat(b.slice(1));
  // The plate fill is triangulated from these rings: a ring that crosses itself would double-blend.
  if (tol > 0.02 && selfIntersects(out)) return simplifyRing(r, tol / 2);
  if (tol !== TOL) console.log(`ring of ${r.length} pts needed tolerance ${tol}`);
  return out;
}

const nation = merge(topo, kept);
const rings = [];
for (const poly of nation.coordinates) {
  const outer = poly[0];
  if (ringArea(outer) < MIN_RING_AREA) continue;
  rings.push(simplifyRing(outer));
}
rings.sort((a, b) => ringArea(b) - ringArea(a));

const interior = mesh(topo, { type: 'GeometryCollection', geometries: kept }, (a, b) => a !== b);
const borders = interior.coordinates.map((l) => dp(l, TOL)).filter((l) => l.length > 1);

const flat = (l) => l.flatMap(([x, y]) => [Math.round(x * 10), Math.round(y * 10)]);
const count = (ls) => ls.reduce((n, l) => n + l.length, 0);

const out = `// GENERATED by check/gen-plate.mjs from us-atlas states-albers-10m (lower 48). Do not edit.
// Coordinates are tenths of a projected unit in the us-atlas Albers frame (975 x 610),
// flattened x,y pairs. Simplified with tolerance ${TOL}.
export const PLATE_W = 975;
export const PLATE_H = 610;
/** Coastline and land border rings, largest first. */
export const NATION_RINGS: readonly (readonly number[])[] = ${JSON.stringify(rings.map(flat))};
/** Interior state borders as open polylines. */
export const STATE_BORDERS: readonly (readonly number[])[] = ${JSON.stringify(borders.map(flat))};
`;
await writeFile(path.join(here, '..', 'plate-data.ts'), out);
console.log(`rings ${rings.length} (${count(rings)} pts), borders ${borders.length} (${count(borders)} pts), ${out.length} bytes`);
